    'PHP max_execution_time: %s seconds' => 'max_execution_time در PHP: %s ثانیه',
    'Shortest step tried: %s seconds' => 'کوتاه‌ترین گام امتحان‌شده: %s ثانیه',
    'Table %1$s (%2$s of %3$s)' => 'جدول %1$s (%2$s از %3$s)',
    '%1$s files found, %2$s' => '%1$s فایل پیدا شد، %2$s',
